<?php
// Incluído pelo admin.php autenticado. Os gráficos usam reservas/pagamentos reais.
$month=date('Y-m-01');$next=date('Y-m-01',strtotime('+1 month',strtotime($month)));
$m=query("SELECT COUNT(*) reservas,COALESCE(SUM(CASE WHEN status<>'Cancelado' THEN TIME_TO_SEC(TIMEDIFF(horario_fim,horario_inicio))/3600 ELSE 0 END),0) horas,COALESCE(SUM(CASE WHEN pagamento_status='Confirmado' THEN valor ELSE 0 END),0) receita,SUM(pagamento_status IN ('Pendente','Solicitado') AND status<>'Cancelado') pendentes,SUM(pagamento_status='Confirmado') pagos,SUM(status='Cancelado') cancelados FROM agendamentos WHERE data>=? AND data<?",[$month,$next])->fetch();
$from=date('Y-m-01',strtotime('-11 months',strtotime($month)));
$monthly=query("SELECT DATE_FORMAT(data,'%Y-%m') mes,COUNT(*) reservas,SUM(CASE WHEN pagamento_status='Confirmado' THEN valor ELSE 0 END) receita FROM agendamentos WHERE data>=? AND data<? GROUP BY mes ORDER BY mes",[$from,$next])->fetchAll();
$indexed=array_column($monthly,null,'mes');$all=[];for($i=0;$i<12;$i++){$key=date('Y-m',strtotime("+$i months",strtotime($from)));$all[]=$indexed[$key]??['mes'=>$key,'reservas'=>0,'receita'=>0];}
$popular=query("SELECT HOUR(horario_inicio) hora,COUNT(*) quantidade FROM agendamentos WHERE status<>'Cancelado' GROUP BY hora ORDER BY quantidade DESC,hora LIMIT 8")->fetchAll();
function bars(array $rows,string $key,string $label,bool $currency=false):void { $max=max(array_merge([1],array_map(fn($r)=>(float)$r[$key],$rows))); ?><div class="bar-chart"><?php foreach($rows as $r):?><div class="bar-row"><span><?=e($r[$label])?></span><div class="bar-track"><div style="width:<?=round((float)$r[$key]/$max*100,2)?>%"></div></div><strong><?=$currency?money($r[$key]):e($r[$key])?></strong></div><?php endforeach;?></div><?php }
?>
<section class="stats dashboard-stats"><?php foreach(['Faturamento do mês'=>money($m['receita']),'Reservas do mês'=>(int)$m['reservas'],'Horas reservadas'=>(float)$m['horas'],'Pagamentos pendentes'=>(int)$m['pendentes'],'Pagamentos confirmados'=>(int)$m['pagos'],'Reservas canceladas'=>(int)$m['cancelados']] as $label=>$value):?><article><div><small><?=e($label)?></small><strong><?=e($value)?></strong></div></article><?php endforeach;?></section><p class="muted">Indicadores do mês por data do jogo. Faturamento inclui pagamentos confirmados; cancelar uma reserva não registra estorno.</p><section class="charts-grid"><article class="review-card"><h3>Faturamento por mês</h3><?php bars($all,'receita','mes',true);?></article><article class="review-card"><h3>Reservas por mês</h3><?php bars($all,'reservas','mes');?></article><article class="review-card"><h3>Horários de início mais reservados</h3><p class="muted">Todo o histórico de reservas ativas.</p><?php foreach($popular as &$r)$r['hora']=str_pad($r['hora'],2,'0',STR_PAD_LEFT).':00';unset($r);bars($popular,'quantidade','hora');if(!$popular):?><p>Nenhuma reserva.</p><?php endif;?></article></section>
